/* eslint-disable @typescript-eslint/no-explicit-any */
import React, { useState } from 'react';
import { Cell, Row } from 'react-table';
import { OnRowReturnType } from '../../Table.types';
import Styled from './TableRow.styles';

interface Props<T> {
  row: Row;
  isRowExpandable: boolean | undefined;
  rowIndex: number;
  dataLength: number;
  expandableRender?: (data: T) => React.ReactNode;
  cellHeight: 'cozy' | 'tight' | 'loose';
  onRowSelect?: (rowData: Row<any>) => void;
  onRow?: (rowData: T, rowIndex: number) => OnRowReturnType;
}

const TableRow = <T,>({
  row,
  isRowExpandable,
  rowIndex,
  dataLength,
  expandableRender,
  cellHeight,
  onRow,
  onRowSelect,
}: Props<T>): JSX.Element => {
  const [expandedRows, setExpandedRows] = useState(() =>
    Array.from(Array(dataLength).keys(), () => false)
  );

  const { onClick: onRowClick, ...onRowRest }: OnRowReturnType = onRow
    ? onRow(row.original as T, rowIndex)
    : {};

  const handleRowExpand = () => {
    if (isRowExpandable) {
      setExpandedRows((prev) => {
        const prevCopy = [...prev];
        prevCopy[rowIndex] = !prevCopy[rowIndex];
        return prevCopy;
      });
    }
  };

  const renderExpandableRowIndicator = () => {
    if (isRowExpandable) {
      return (
        <Styled.Td cellHeight={cellHeight}>
          <Styled.Chevron
            onClick={handleRowExpand}
            size="medium"
            expanded={expandedRows[rowIndex]}
          />
        </Styled.Td>
      );
    }
    if (expandableRender) {
      return <Styled.Td />;
    }
    return null;
  };

  const handleRowClick = (e: React.MouseEvent<HTMLTableRowElement>) => {
    onRowSelect?.(row);
    if (onRowClick) {
      onRowClick(e);
    }
  };

  return (
    <>
      <Styled.Tr
        onClick={handleRowClick}
        rowClickable={!!onRowClick || !!onRowSelect}
        selected={row.isSelected}
        {...onRowRest}
        {...row.getRowProps()}
      >
        {renderExpandableRowIndicator()}
        {row.cells.map((cell: Cell) => (
          <Styled.Td
            {...cell.getCellProps()}
            alignment={cell.column?.alignment}
            cellHeight={cellHeight}
            key={cell.getCellProps().key}
          >
            {cell.column?.customRender && typeof cell.column?.customRender === 'function'
              ? cell.column?.customRender(cell.value, cell.row.original)
              : cell.render('Cell')}
          </Styled.Td>
        ))}
      </Styled.Tr>
      {isRowExpandable && (
        <Styled.ExpandedSection expanded={expandedRows[rowIndex]}>
          {/* //!fix the length + 1 to acomodate expand and/or selectable */}
          <td style={{ padding: 0 }} colSpan={row.cells.length + 1}>
            <Styled.ExpandedContent expanded={expandedRows[rowIndex]}>
              {expandableRender && expandableRender(row?.original as T)}
            </Styled.ExpandedContent>
          </td>
        </Styled.ExpandedSection>
      )}
    </>
  );
};

export default TableRow;
